import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.mRCPFc5l.js";const x=JSON.parse('{"title":"配置 Codex","description":"","frontmatter":{},"headers":[],"relativePath":"relay/codex.md","filePath":"relay/codex.md","lastUpdated":1786861842000}'),l={name:"relay/codex.md"};function i(r,e,s,c,n,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="配置-codex" tabindex="-1">配置 Codex <a class="header-anchor" href="#配置-codex" aria-label="Permalink to &quot;配置 Codex&quot;">​</a></h1><h2 id="从控制台生成配置" tabindex="-1">从控制台生成配置 <a class="header-anchor" href="#从控制台生成配置" aria-label="Permalink to &quot;从控制台生成配置&quot;">​</a></h2><p>在 API 密钥列表打开 <strong>使用密钥</strong>，选择 <strong>Codex</strong>，再按系统标签复制完整配置。控制台生成的内容会匹配当前分组和认证方式，是唯一推荐来源。</p><h2 id="配置位置" tabindex="-1">配置位置 <a class="header-anchor" href="#配置位置" aria-label="Permalink to &quot;配置位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>常见目录</th></tr></thead><tbody><tr><td>macOS / Linux</td><td><code>~/.codex/config.toml</code>、<code>~/.codex/auth.json</code></td></tr><tr><td>Windows</td><td><code>%USERPROFILE%\\.codex\\config.toml</code>、<code>%USERPROFILE%\\.codex\\auth.json</code></td></tr></tbody></table><p>如果目录不存在，按弹窗提示创建；不要把完整文件上传到工单或公开仓库。</p><h2 id="保存并验证" tabindex="-1">保存并验证 <a class="header-anchor" href="#保存并验证" aria-label="Permalink to &quot;保存并验证&quot;">​</a></h2><ol><li><p>复制控制台为当前系统生成的内容。</p></li><li><p>完全退出 Codex CLI 或 Desktop，再重新打开。</p></li><li><p>新建一个任务，发送只读的小请求：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请回复“连接成功”，不要读取或修改任何文件。</span></span></code></pre></div></li><li><p>请求成功后再开始正常工作。</p></li></ol><p>Codex Desktop 可能缓存旧配置，只切换窗口不会重新加载。若控制台提供 <strong>API Key Mode</strong>，按弹窗推荐模式操作；不要自行混用两种模式。</p><h2 id="仍未生效时" tabindex="-1">仍未生效时 <a class="header-anchor" href="#仍未生效时" aria-label="Permalink to &quot;仍未生效时&quot;">​</a></h2><ul><li>检查密钥状态为活跃，且已绑定可用的 Codex 分组。</li><li>重新从 <strong>使用密钥</strong> 复制，不要手动改 <code>base_url</code>、认证字段或模型名。</li><li>完全退出所有 Codex 进程，确认旧环境变量没有覆盖新配置。</li><li>记录状态码后查看<a href="/relay/troubleshooting">常见错误</a>。</li></ul><div class="warning custom-block"><p class="custom-block-title">配置文件保密</p><p><code>auth.json</code> 和包含 <code>env_key</code>/Key 值的配置文件都不可提交到仓库。报告问题时只贴去掉密钥后的字段名和错误堆栈。</p></div>',12)])])}const u=t(l,[["render",i]]);export{x as __pageData,u as default};
